import json

# Example of safely parsing a JSON string instead of using eval
data_str = '{"key": "value"}'
try:
    data = json.loads(data_str)
    print(data)  # {'key': 'value'}
except json.JSONDecodeError:
    print("Invalid JSON data")

import json

# Example of serializing a dictionary to JSON
product_data = {"color": "red", "size": "M"}
serialized_data = json.dumps(product_data)
print(serialized_data)  # Output: {"color": "red", "size": "M"}

# Example of deserializing JSON back to a dictionary
deserialized_data = json.loads(serialized_data)
print(deserialized_data)  # Output: {'color': 'red', 'size': 'M'}
